import{_ as s,o as n,c as l,ag as e}from"./chunks/framework.CvZZEx4j.js";const u=JSON.parse('{"title":"导出角色卡","description":"","frontmatter":{},"headers":[],"relativePath":"card-author/export.md","filePath":"card-author/export.md","lastUpdated":null}'),i={name:"card-author/export.md"};function t(o,a,p,r,c,d){return n(),l("div",null,[...a[0]||(a[0]=[e(`<h1 id="导出角色卡" tabindex="-1">导出角色卡 <a class="header-anchor" href="#导出角色卡" aria-label="Permalink to &quot;导出角色卡&quot;">​</a></h1><h2 id="导出为-png-角色卡" tabindex="-1">导出为 PNG 角色卡 <a class="header-anchor" href="#导出为-png-角色卡" aria-label="Permalink to &quot;导出为 PNG 角色卡&quot;">​</a></h2><p>这是推荐的分发方式——导出的 PNG 文件里包含了完整的角色卡数据 + 插件配置，用户导入即可使用。</p><h3 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li>打开 <strong>资源管理器</strong></li><li>点击顶部的 <strong>导出</strong> 按钮</li><li>选择 <strong>「导出角色卡 PNG」</strong></li><li>插件会自动将以下配置嵌入到角色卡中： <ul><li>📦 资源包配置（远程图包地址）</li><li>💃 Live2D 模型绑定（URL + 位置/缩放）</li><li>🔊 TTS 角色音色绑定</li><li>🎵 BGM 白名单</li></ul></li><li>下载生成的 PNG 文件</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>导出的 PNG 文件就是最终分发物——直接分享给用户即可。</p></div><h2 id="远程资源托管" tabindex="-1">远程资源托管 <a class="header-anchor" href="#远程资源托管" aria-label="Permalink to &quot;远程资源托管&quot;">​</a></h2><p>由于角色卡 PNG 的体积有限，立绘、背景等图片资源通常不会直接嵌入卡中，而是存储在远程服务器上。</p><h3 id="为什么需要远程托管" tabindex="-1">为什么需要远程托管 <a class="header-anchor" href="#为什么需要远程托管" aria-label="Permalink to &quot;为什么需要远程托管&quot;">​</a></h3><ul><li>角色卡 PNG 容量有限，无法存放大量高清图片</li><li>远程托管让用户导入后 <strong>按需加载</strong>，不影响导入速度</li><li>更新资源时只需更新远程文件，无需重新导出角色卡</li></ul><h3 id="使用-github-托管-推荐免费方案" tabindex="-1">使用 GitHub 托管（推荐免费方案） <a class="header-anchor" href="#使用-github-托管-推荐免费方案" aria-label="Permalink to &quot;使用 GitHub 托管（推荐免费方案）&quot;">​</a></h3><ol><li><strong>创建 GitHub 仓库</strong>，上传你的资源文件</li><li>在资源管理器中，点击 <strong>导出</strong> → <strong>导出远程资源包</strong></li><li>将生成的 <code>remote_assets.json</code> 也上传到仓库</li><li>回到资源管理器，在远程地址配置中填写你的 <strong>GitHub 仓库地址</strong><ul><li>格式：<code>https://github.com/你的用户名/仓库名</code></li><li>插件会自动将 GitHub 地址转换为 jsDelivr CDN 加速链接</li></ul></li><li>重新 <strong>导出角色卡 PNG</strong>，远程地址会一并嵌入</li></ol><h3 id="仓库目录结构建议" tabindex="-1">仓库目录结构建议 <a class="header-anchor" href="#仓库目录结构建议" aria-label="Permalink to &quot;仓库目录结构建议&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的仓库/</span></span>
<span class="line"><span>├── remote_assets.json    ← 资源索引文件</span></span>
<span class="line"><span>├── sprites/              ← 立绘图片</span></span>
<span class="line"><span>│   ├── 角色名_默认.png</span></span>
<span class="line"><span>│   ├── 角色名_微笑.png</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>├── backgrounds/          ← 背景图片</span></span>
<span class="line"><span>│   ├── 教室.png</span></span>
<span class="line"><span>│   ├── 公园.png</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>└── live2d/               ← Live2D 模型（可选）</span></span>
<span class="line"><span>    └── 角色名/</span></span>
<span class="line"><span>        ├── model3.json</span></span>
<span class="line"><span>        └── ...</span></span></code></pre></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>导出完成后，进入 <a href="/galgame/card-author/verify.html">验证与分发</a> 确保一切正常。</p>`,16)])])}const g=s(i,[["render",t]]);export{u as __pageData,g as default};
